<?php require __DIR__ . '/_bootstrap.php';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { $id=(int)($_POST['idResultat']??0); $note=$_POST['note']??''; if($id>0 && is_numeric($note) && $note>=0 && $note<=20){$q=$db->prepare('UPDATE resultat r INNER JOIN evaluation e ON e.idEvaluation=r.idEvaluation INNER JOIN module m ON m.idModule=e.idModule SET r.note=:note,r.appreciation=:appreciation,r.datePublication=NOW() WHERE r.idResultat=:id AND m.idFormateur=:formateur');$q->execute(['note'=>$note,'appreciation'=>trim($_POST['appreciation']??''),'id'=>$id,'formateur'=>$formateurId]);journaliserAction('Modification d’une note','Résultat #'.$id);flashMessage('success','Note enregistrée avec succès.');}else{flashMessage('error','La note doit être comprise entre 0 et 20.');}header('Location: '.BASE_URL.'views/formateur/notes.php');exit;}
$q=$db->prepare('SELECT r.idResultat,r.note,r.appreciation,e.titre,m.libelle AS module,u.prenom,u.nom FROM resultat r INNER JOIN evaluation e ON e.idEvaluation=r.idEvaluation INNER JOIN module m ON m.idModule=e.idModule INNER JOIN etudiant et ON et.idUtilisateur=r.idEtudiant INNER JOIN utilisateur u ON u.idUtilisateur=et.idUtilisateur WHERE m.idFormateur=:id ORDER BY e.dateLimite DESC,u.nom');$q->execute(['id'=>$formateurId]);$resultats=$q->fetchAll();$pageTitle='Saisie des notes';$activeMenu='notes';require __DIR__.'/../../includes/header.php'; ?>
<div class="card" style="overflow-x:auto"><h2>Saisie des notes</h2><table class="director-table"><thead><tr><th>Évaluation</th><th>Étudiant</th><th>Note /20</th><th>Appréciation</th><th>Action</th></tr></thead><tbody><?php foreach($resultats as $resultat): ?><tr><td><?=htmlspecialchars($resultat['module'].' - '.$resultat['titre'])?></td><td><?=htmlspecialchars($resultat['prenom'].' '.$resultat['nom'])?></td><td><form method="post"><input type="hidden" name="idResultat" value="<?=$resultat['idResultat']?>"><input type="number" name="note" min="0" max="20" step="0.01" value="<?=htmlspecialchars($resultat['note']??'')?>" required></td><td><input name="appreciation" value="<?=htmlspecialchars($resultat['appreciation']??'')?>"></td><td><button class="btn" type="submit">Enregistrer</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__.'/../../includes/footer.php'; ?>